    function plural(n, noun) {
        const table = (PLURALS[currentLocale] && PLURALS[currentLocale][noun]) || PLURALS.en[noun];
        if (!table) return n === 1 ? noun : noun + 's';
        let cat = 'other';
        try { cat = new Intl.PluralRules(LOCALE_TAGS[currentLocale] || 'en').select(n); } catch (e) {}
        return table[cat] || table.other || table.one || noun;
    }

    function detectLocale() {
        // 'ar' ships but is only partially translated and has no RTL layout yet,
        // so never auto-select or restore it — it stays hidden until completed.
        const usable = l => l && TRANSLATIONS[l] && l !== 'ar';
        // 1. Check saved preference
        const saved = localStorage.getItem('happymoments_locale');
        if (usable(saved)) return saved;

        // 2. Check full browser language tag (e.g. 'pt-BR')
        const browserFull = (navigator.language || 'en').replace('-', '_');
        if (usable(browserFull)) return browserFull;

        // 3. Check base language
        const browserLang = browserFull.split('_')[0].toLowerCase();
        if (usable(browserLang)) return browserLang;

        // 4. Check variants
        if (['sr', 'bs'].includes(browserLang)) return 'hr';
        if (browserLang === 'ms') return 'id'; // Malay → Indonesian
        if (['uk', 'be'].includes(browserLang)) return 'ru'; // Ukrainian/Belarusian → Russian

        return 'en';
    }

    function applyTranslations() {
        // Apply to all elements with data-i18n attribute
        document.querySelectorAll('[data-i18n]').forEach(el => {
            const key = el.getAttribute('data-i18n');
            const val = t(key);
            if (el.tagName === 'INPUT' && el.type !== 'checkbox') {
                el.placeholder = val;
            } else if (el.tagName === 'OPTION') {
                el.textContent = val;
            } else {
                el.textContent = val;
            }
        });
        // Keys whose value contains markup (e.g. <strong>) — translations may
        // only use the same tags as the English source (validated by tooling)
        document.querySelectorAll('[data-i18n-html]').forEach(el => {
            el.innerHTML = t(el.getAttribute('data-i18n-html'));
        });

        // Apply to data-i18n-placeholder
        document.querySelectorAll('[data-i18n-placeholder]').forEach(el => {
            el.placeholder = t(el.getAttribute('data-i18n-placeholder'));
        });
    }

    function init() {
        const locale = detectLocale();
        setLocale(locale);
    }

